#include <stdio.h>

#define MAXN 100005

int bit[MAXN];
int val[MAXN];
int N, Q;

void update(int idx, int delta) {
    for (; idx <= N; idx += idx & -idx) {
        bit[idx] += delta;
    }
}

int query(int idx) {
    int sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

int main() {
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    for (int i = 1; i <= N; i++) {
        scanf("%d", &val[i]);
        update(i, val[i]);
    }

    for (int i = 0; i < Q; i++) {
        int type;
        scanf("%d", &type);
        if (type == 0) {
            int k, p;
            scanf("%d %d", &k, &p);
            update(k, p - val[k]);
            val[k] = p;
        } else {
            int k;
            scanf("%d", &k);
            printf("%d\n", query(k));
        }
    }

    return 0;
}
